result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/sql_where.py", "content": """"Mini SQL WHERE-clause expression evaluator.

Filtering core of a CSV query tool. Grammar (lowest precedence first):

    expr       := or_expr
    or_expr    := and_expr (OR and_expr)*
    and_expr   := not_expr (AND not_expr)*
    not_expr   := NOT not_expr | predicate
    predicate  := '(' expr ')' | operand comp_op operand
    comp_op    := '=' | '!=' | '<' | '<=' | '>' | '>='
    operand    := column_identifier | int_literal | float_literal | string_literal

Precedence (tightest to loosest): parentheses, NOT, comparisons, AND, OR.
AND/OR are left-associative.

Stdlib only.
"""

from __future__ import annotations

import csv
import re
from dataclasses import dataclass

__all__ = [
    "Expr", "Column", "Lit", "Cmp", "Not", "And", "Or",
    "parse", "eval_where", "filter_csv", "WhereSyntaxError",
]


class WhereSyntaxError(ValueError):
    """Raised when a WHERE expression cannot be parsed."""


# --------------------------------------------------------------------------
# AST
# --------------------------------------------------------------------------

@dataclass(frozen=True)
class Column:
    """A column identifier, e.g. `price`."""
    name: str


@dataclass(frozen=True)
class Lit:
    """An int, float or string literal, e.g. `1`, `2.5`, `'alpha'`."""
    value: object


@dataclass(frozen=True)
class Cmp:
    """Comparison: left <op> right, op in = != < <= > >=."""
    op: str
    left: object
    right: object


@dataclass(frozen=True)
class Not:
    operand: object


@dataclass(frozen=True)
class And:
    left: object
    right: object


@dataclass(frozen=True)
class Or:
    left: object
    right: object


Expr = (Column, Lit, Cmp, Not, And, Or)


# --------------------------------------------------------------------------
# Tokenizer
# --------------------------------------------------------------------------

_TOKEN_RE = re.compile(
    r"""
      (?P<ws>\s+)
    | (?P<float>\d+\.\d+)
    | (?P<int>\d+)
    | (?P<string>'[^']*'|"[^"]*")
    | (?P<ident>[A-Za-z_][A-Za-z_0-9]*)
    | (?P<op><=|>=|!=|=|<|>)
    | (?P<lparen>\()
    | (?P<rparen>\))
    """,
    re.VERBOSE,
)

_KEYWORDS = {"and": "AND", "or": "OR", "not": "NOT"}


def tokenize(text: str) -> list[tuple[str, object]]:
    tokens: list[tuple[str, object]] = []
    pos = 0
    while pos < len(text):
        m = _TOKEN_RE.match(text, pos)
        if m is None:
            raise WhereSyntaxError(
                f"unexpected character {text[pos]!r} at position {pos}"
            )
        pos = m.end()
        kind = m.lastgroup
        lexeme = m.group()
        if kind == "ws":
            continue
        if kind in ("int", "float"):
            value = int(lexeme) if kind == "int" else float(lexeme)
            tokens.append(("literal", value))
        elif kind == "string":
            tokens.append(("literal", lexeme[1:-1]))
        elif kind == "ident":
            keyword = _KEYWORDS.get(lexeme.lower())
            if keyword:
                tokens.append((keyword, lexeme))
            else:
                tokens.append(("ident", lexeme))
        elif kind == "op":
            tokens.append(("op", lexeme))
        else:  # lparen / rparen
            tokens.append((kind, lexeme))
    return tokens


# --------------------------------------------------------------------------
# Recursive-descent parser
# --------------------------------------------------------------------------

class _Parser:
    def __init__(self, text: str):
        self.text = text
        self.tokens = tokenize(text)
        self.pos = 0

    # -- token helpers ------------------------------------------------------

    def peek(self) -> tuple[str, object] | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def next(self) -> tuple[str, object]:
        tok = self.peek()
        if tok is None:
            raise WhereSyntaxError(
                f"unexpected end of expression: {self.text!r}"
            )
        self.pos += 1
        return tok

    def expect(self, kind: str) -> tuple[str, object]:
        tok = self.next()
        if tok[0] != kind:
            raise WhereSyntaxError(
                f"expected {kind}, got {tok[1]!r} in {self.text!r}"
            )
        return tok

    # -- grammar rules ------------------------------------------------------

    def parse(self):
        node = self.or_expr()
        if self.peek() is not None:
            tok = self.peek()
            raise WhereSyntaxError(
                f"unexpected trailing token {tok[1]!r} in {self.text!r}"
            )
        return node

    def or_expr(self):
        node = self.and_expr()
        while self.peek() and self.peek()[0] == "OR":
            self.next()
            node = Or(node, self.and_expr())
        return node

    def and_expr(self):
        node = self.not_expr()
        while self.peek() and self.peek()[0] == "AND":
            self.next()
            node = And(node, self.not_expr())
        return node

    def not_expr(self):
        if self.peek() and self.peek()[0] == "NOT":
            self.next()
            return Not(self.not_expr())
        return self.predicate()

    def predicate(self):
        if self.peek() and self.peek()[0] == "lparen":
            self.next()
            node = self.or_expr()
            self.expect("rparen")
            return node
        left = self.operand()
        tok = self.next()
        if tok[0] != "op":
            raise WhereSyntaxError(
                f"expected comparison operator after {left!r}, "
                f"got {tok[1]!r} in {self.text!r}"
            )
        right = self.operand()
        return Cmp(tok[1], left, right)

    def operand(self):
        kind, value = self.next()
        if kind == "ident":
            return Column(value)
        if kind == "literal":
            return Lit(value)
        raise WhereSyntaxError(
            f"expected column or literal, got {value!r} in {self.text!r}"
        )


def parse(where_string: str):
    """Parse a WHERE expression string into an AST rooted at a boolean node."""
    if not where_string.strip():
        raise WhereSyntaxError("empty WHERE expression")
    return _Parser(where_string).parse()


# --------------------------------------------------------------------------
# Evaluation
# --------------------------------------------------------------------------

def _coerce(raw: str):
    """Convert a raw CSV cell to int, float, or leave as str."""
    try:
        return int(raw)
    except ValueError:
        pass
    try:
        return float(raw)
    except ValueError:
        return raw


def _is_number(value) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _compare(op: str, left, right) -> bool:
    # Numeric comparison when both sides are numbers; otherwise compare
    # string representations (so 'x' = 'x' works against text columns).
    if _is_number(left) and _is_number(right):
        pass
    else:
        left, right = str(left), str(right)
    if op == "=":
        return left == right
    if op == "!=":
        return left != right
    if op == "<":
        return left < right
    if op == "<=":
        return left <= right
    if op == ">":
        return left > right
    if op == ">=":
        return left >= right
    raise WhereSyntaxError(f"unknown operator {op!r}")


def eval_where(ast, row: dict) -> bool:
    """Evaluate an AST against a row dict of raw (string) CSV cells."""
    if isinstance(ast, Or):
        return eval_where(ast.left, row) or eval_where(ast.right, row)
    if isinstance(ast, And):
        return eval_where(ast.left, row) and eval_where(ast.right, row)
    if isinstance(ast, Not):
        return not eval_where(ast.operand, row)
    if isinstance(ast, Cmp):
        left = _operand_value(ast.left, row)
        right = _operand_value(ast.right, row)
        return _compare(ast.op, left, right)
    raise TypeError(f"not a boolean AST node: {ast!r}")


def _operand_value(node, row: dict):
    if isinstance(node, Column):
        if node.name not in row:
            raise KeyError(f"no such column: {node.name!r}")
        return _coerce(row[node.name])
    if isinstance(node, Lit):
        return node.value
    raise TypeError(f"not an operand node: {node!r}")


# --------------------------------------------------------------------------
# CSV filtering
# --------------------------------------------------------------------------

def filter_csv(path: str, where_string: str) -> list[dict]:
    """Return all rows of the CSV file matching the WHERE expression.

    Rows are returned as dicts keyed by the header row (values kept as
    raw strings), in file order.
    """
    ast = parse(where_string)
    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        return [row for row in reader if eval_where(ast, row)]


if __name__ == "__main__":
    import sys

    if len(sys.argv) != 3:
        sys.exit("usage: python sql_where.py <csv-path> <where-expression>")
    for matched in filter_csv(sys.argv[1], sys.argv[2]):
        print(matched)
